local ShawmMaker = {}
local PRODUCTS = {
    soprano_shawm = { name = "Soprano šalmaj", woodCost = 1, reedCost = 1, time = 1, cost = 18, soundQuality = 9, prestige = 1, description = "Soprano šalmaj za ulične glasbenike." },
    alto_shawm = { name = "Alt šalmaj", woodCost = 2, reedCost = 1, time = 3, cost = 55, soundQuality = 12, prestige = 2, description = "Alt šalmaj z močnim zvokom." },
    tenor_shawm = { name = "Tenor šalmaj", woodCost = 2, brassCost = 1, reedCost = 1, time = 5, cost = 140, soundQuality = 16, prestige = 4, happiness = 1, description = "Tenor šalmaj z medeninastim zvonom." },
    bombarde = { name = "Bombarda", woodCost = 3, brassCost = 1, reedCost = 2, time = 7, cost = 320, soundQuality = 20, prestige = 8, happiness = 2, description = "Bombarda za močan basov zvok." },
    silver_shawm = { name = "Srebrni šalmaj", woodCost = 3, silverCost = 1, reedCost = 2, time = 9, cost = 700, soundQuality = 25, prestige = 14, happiness = 3, description = "Srebrni šalmaj za dvorne koncerte." },
    royal_double_reed_consort = { name = "Kraljevski dvojni konzort", woodCost = 4, goldCost = 2, silverCost = 1, ivoryCost = 1, reedCost = 3, time = 13, cost = 1900, soundQuality = 38, prestige = 48, happiness = 9, description = "Veliki kraljevski konzort dvojnih rožičev z zlatim okovjem in slonovino." },
}
local BUILDINGS = {
    workshop = { name = "Šalmajska delavnica", cost = { gold = 260, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    boring_room = { name = "Vrtalnica", cost = { gold = 800, wood = 220, stone = 200, brass = 6 }, upkeep = 20, qualityBonus = 18 },
    reed_room = { name = "Trobilnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, reed = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_shawm_atelier = { name = "Kraljevski atelje šalmajev", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, ivory = 20 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
ShawmMaker.woodStock = 14; ShawmMaker.reedStock = 12; ShawmMaker.brassStock = 8; ShawmMaker.silverStock = 6; ShawmMaker.goldStock = 6; ShawmMaker.ivoryStock = 6
ShawmMaker.productStock = {}; ShawmMaker.buildings = {}; ShawmMaker.maker = nil; ShawmMaker.activeMaking = {}; ShawmMaker.totalProducts = 0; ShawmMaker.dayTimer = 0
function ShawmMaker.init() ShawmMaker.woodStock=14; ShawmMaker.reedStock=12; ShawmMaker.brassStock=8; ShawmMaker.silverStock=6; ShawmMaker.goldStock=6; ShawmMaker.ivoryStock=6; ShawmMaker.productStock={}; ShawmMaker.buildings={}; ShawmMaker.maker=nil; ShawmMaker.activeMaking={}; ShawmMaker.totalProducts=0; ShawmMaker.dayTimer=0; print("[ShawmMaker] Royal Shawm Maker System initialized (6 products, 4 buildings)") end
function ShawmMaker.hireMaker(n,s) s=s or math.random(50,90); local c=470+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ShawmMaker.maker={name=n or ("Šalmajar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šalmajar najet: %s (spretnost: %d)",ShawmMaker.maker.name,s),"success") end; return true end
function ShawmMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ShawmMaker.build(id) local ok,e=ShawmMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ShawmMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ShawmMaker.getQualityBonus() local b=0; for _,bd in ipairs(ShawmMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ShawmMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ShawmMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.reedCost and ShawmMaker.reedStock<(d.reedCost or 0) then return false,"Premalo trobil" end; if d.brassCost and ShawmMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ShawmMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ShawmMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.ivoryCost and ShawmMaker.ivoryStock<(d.ivoryCost or 0) then return false,"Premalo slonovine" end; if #ShawmMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ShawmMaker.maker then return false,"Potreben šalmajar" end; return true end
function ShawmMaker.make(pt,qty) qty=qty or 1; local ok,e=ShawmMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ShawmMaker.woodStock=ShawmMaker.woodStock-d.woodCost*qty end; if d.reedCost then ShawmMaker.reedStock=ShawmMaker.reedStock-d.reedCost*qty end; if d.brassCost then ShawmMaker.brassStock=ShawmMaker.brassStock-d.brassCost*qty end; if d.silverCost then ShawmMaker.silverStock=ShawmMaker.silverStock-d.silverCost*qty end; if d.goldCost then ShawmMaker.goldStock=ShawmMaker.goldStock-d.goldCost*qty end; if d.ivoryCost then ShawmMaker.ivoryStock=ShawmMaker.ivoryStock-d.ivoryCost*qty end; local t=d.time; if ShawmMaker.maker then t=math.max(1,t-math.floor(ShawmMaker.maker.skill/12)) end; table.insert(ShawmMaker.activeMaking,{id="shawm_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ShawmMaker.completeMaking(m) local q=1.0+(ShawmMaker.getQualityBonus()/100); if ShawmMaker.maker then q=q+(ShawmMaker.maker.skill/180) end; q=math.min(2.0,q); ShawmMaker.productStock[m.productType]=(ShawmMaker.productStock[m.productType] or 0)+m.quantity; ShawmMaker.totalProducts=ShawmMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ShawmMaker.maker then ShawmMaker.maker.itemsMade=ShawmMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then ShawmMaker.maker.skill=math.min(100,ShawmMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šalmaj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"shawm.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function ShawmMaker.update(dt) if not _G.state then return end; ShawmMaker.dayTimer=ShawmMaker.dayTimer+dt; if ShawmMaker.dayTimer>=30 then ShawmMaker.dayTimer=0; for i=#ShawmMaker.activeMaking,1,-1 do local m=ShawmMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ShawmMaker.completeMaking(m); table.remove(ShawmMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ShawmMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ShawmMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ShawmMaker.getStats() return {woodStock=ShawmMaker.woodStock,reedStock=ShawmMaker.reedStock,brassStock=ShawmMaker.brassStock,silverStock=ShawmMaker.silverStock,goldStock=ShawmMaker.goldStock,ivoryStock=ShawmMaker.ivoryStock,productStock=ShawmMaker.productStock,numBuildings=#ShawmMaker.buildings,hasMaker=ShawmMaker.maker~=nil,makerName=ShawmMaker.maker and ShawmMaker.maker.name or "—",makerSkill=ShawmMaker.maker and ShawmMaker.maker.skill or 0,activeMaking=#ShawmMaker.activeMaking,totalProducts=ShawmMaker.totalProducts} end
return ShawmMaker
